        // arguments), so we know how much space is left over for the paths.
        let mut base_len = self.args[0].generate("", None).len() + 1;
        for arg in &self.args[1..] {
            if !arg.has_tokens() {
                base_len += arg.generate("", None).len() + 1;
            }
        }

        // Leave some slack for the environment and other overhead the OS/shell
        // needs, so we don't run right up against the limit.
        let max_arg_length = get_arg_max()
            .saturating_sub(base_len)
            .saturating_sub(2048)
            .max(4096);

        let mut results: Vec<ExitCode> = Vec::new();
        let mut chunk: Vec<PathBuf> = Vec::new();
        let mut chunk_len = 0usize;

        for path in paths {
            let path_len = strip_current_dir(&path).as_os_str().len() + 1;

            if !chunk.is_empty() && chunk_len + path_len > max_arg_length {
                results.push(self.execute_batch_chunk(&chunk, buffer_output));
